component.script:
(() => {
var root=document.getElementById("fpRoot"),cv=document.getElementById("fpCv"),g=cv.getContext("2d"),mir=document.getElementById("fpMir"),mg=mir.getContext("2d"),fl=document.getElementById("fpFlash"),wh=document.getElementById("fpWh"),bgm=document.getElementById("fpBgm");
var IW=320,IH=180,MW=96,MH=54;
var D=String.fromCharCode(36),SL=String.fromCharCode(47),NEXT="大都会真结局追逐战";
var W=1.7,L=22,BK=-1.2;
var px=0,py=1.2,ang=1.5708,pitch=0,bobP=0;
var K={w:0,s:0,a:0,d:0,q:0,e:0},velF=0,velS=0;
var loops=0,backs=0,frr=false,gone=false,started=0,stT=0,fc=0,flick=1,whT=null;
var FWDW=["出口，没有变近。","向前的路，只是折叠回起点。","……试试倒退。","它在你身后。"];
var clamp=(v,a,b)=>v<a?a:v>b?b:v;
var mkc=(w,h)=>{var c=document.createElement("canvas");c.width=w;c.height=h;return c};
var wallC=mkc(64,64),doorC=mkc(64,64),doorG=mkc(64,64);
(function(){
var t=wallC.getContext("2d"),i;
t.fillStyle="#575d64";t.fillRect(0,0,64,64);
for(i=0;i<460;i++){t.fillStyle=Math.random()<0.5?"rgba(16,18,21,.18)":"rgba(148,156,164,.13)";t.fillRect(Math.random()*64|0,Math.random()*64|0,2,1)}
for(i=1;i<4;i++){t.fillStyle="#31363c";t.fillRect(0,i*16-1,64,2)}
t.fillStyle="#23272c";t.fillRect(0,0,64,3);t.fillRect(0,60,64,4);
t.fillStyle="#69717a";t.fillRect(52,4,7,56);
t.fillStyle="#3b4248";t.fillRect(58,4,1,56);t.fillRect(52,26,7,2);
t.fillStyle="rgba(14,16,19,.4)";t.fillRect(7,36,10,20);t.fillRect(32,20,6,36);
})();
(function(){
var t=doorC.getContext("2d");
t.fillStyle="#343a41";t.fillRect(0,0,64,64);
t.fillStyle="#4a5159";t.fillRect(5,4,54,60);
t.fillStyle="#1d2126";t.fillRect(5,4,54,3);t.fillRect(5,4,3,60);t.fillRect(56,4,3,60);
t.fillStyle="#15181c";t.fillRect(27,32,10,32);
t.fillStyle="#8b949d";t.fillRect(37,44,12,3);t.fillRect(37,51,12,3);
t.fillStyle="#262b31";t.fillRect(15,14,34,3);
})();
(function(){
var t=doorG.getContext("2d");
t.drawImage(doorC,0,0);
t.fillStyle="rgba(110,255,190,.24)";t.fillRect(0,0,64,64);
t.fillStyle="#c8ffe6";t.fillRect(30,8,4,4);t.fillRect(30,16,4,4);
})();
var wallD=wallC.getContext("2d").getImageData(0,0,64,64).data;
var doorD=doorC.getContext("2d").getImageData(0,0,64,64).data;
var doorGD=doorG.getContext("2d").getImageData(0,0,64,64).data;
var buf=g.createImageData(IW,IH),mbuf=mg.createImageData(MW,MH);
var zb=new Float32Array(IW),mzb=new Float32Array(MW);
var render=(ctx,w,h,img,zb2,dx,dy,cy)=>{
  var dat=img.data,r,c;
  var plx=-dy*0.66,ply=dx*0.66;
  var d0x=dx-plx,d0y=dy-ply,d1x=dx+plx,d1y=dy+ply;
  var pz=h*0.5;
  for(r=0;r<h;r++){
    var isF=r>cy,p=isF?r-cy:cy-r;
    if(p<0.5)p=0.5;
    var rd=pz*p**-1;
    var fogF=(1+rd*rd*0.05)**-1;
    var fx=px+rd*d0x,fy=py+rd*d0y;
    var sx=rd*(d1x-d0x)*w**-1,sy=rd*(d1y-d0y)*w**-1;
    var o=r*w*4,br,bgc,sh2;
    if(isF){br=0.85;sh2=0.42}else{br=0.55;sh2=0.42}
    for(c=0;c<w;c++){
      var gx=fx-Math.floor(fx),gy=fy-Math.floor(fy),e=br,lum=0;
      if(!isF&&gy>0.1&&gy<0.24){e=1.6;lum=1}
      var sh=e*fogF*flick;
      if(lum){dat[o]=188*sh;dat[o+1]=222*sh;dat[o+2]=200*sh}
      else if(sh<sh2){dat[o]=34*sh;dat[o+1]=37*sh;dat[o+2]=41*sh}
      else{dat[o]=64*sh;dat[o+1]=65*sh;dat[o+2]=62*sh}
      dat[o+3]=255;
      fx+=sx;fy+=sy;o+=4;
    }
  }
  for(c=0;c<w;c++){
    var cxr=(2*c)*w**-1-1;
    var rx=dx+plx*cxr,ry=dy+ply*cxr;
    var t=1e9,u=0,td=wallD,sd=0.8,tp,hx,hy;
    if(rx>1e-6){tp=(W-px)*rx**-1;hy=py+ry*tp;if(tp>0&&tp<t&&hy>BK&&hy<L){t=tp;u=hy}}
    if(rx<-1e-6){tp=(-W-px)*rx**-1;hy=py+ry*tp;if(tp>0&&tp<t&&hy>BK&&hy<L){t=tp;u=hy}}
    if(ry>1e-6){tp=(L-py)*ry**-1;hx=px+rx*tp;if(tp>0&&tp<t&&hx>-W&&hx<W){t=tp;u=hx;td=frr?doorGD:doorD;sd=1}}
    if(ry<-1e-6){tp=(BK-py)*ry**-1;hx=px+rx*tp;if(tp>0&&tp<t&&hx>-W&&hx<W){t=tp;u=hx;sd=0.45}}
    if(t>900)continue;
    zb2[c]=t;
    var half=pz*t**-1;
    var y0=cy-half,y1=cy+half;
    var iy0=Math.max(0,y0|0),iy1=Math.min(h-1,y1|0);
    var tu=((u-Math.floor(u))*64)|0;
    var fs=(1+t*t*0.03)**-1*flick*sd;
    var vs=64*(y1-y0)**-1,tv=(iy0-y0)*vs;
    for(r=iy0;r<=iy1;r++){
      var o=(r*w+c)*4,ti=(((tv|0)&63)*64+tu)*4;
      dat[o]=td[ti]*fs;dat[o+1]=td[ti+1]*fs;dat[o+2]=td[ti+2]*fs;dat[o+3]=255;
      tv+=vs;
    }
  }
  ctx.putImageData(img,0,0);
};
var whisper=(txt)=>{
  wh.textContent=txt;wh.classList.add("is-on");
  if(whT)clearTimeout(whT);
  whT=setTimeout(()=>wh.classList.remove("is-on"),3600);
};
var glitch=(dir)=>{
  fl.style.transition="opacity .1s";fl.style.opacity="1";
  setTimeout(()=>{fl.style.opacity="0"},140);
  root.classList.remove("is-shake");void root.offsetWidth;root.classList.add("is-shake");
  if(dir===1){loops++;py=1.2;px=0;whisper(FWDW[Math.min(loops-1,3)])}
  else{backs++;py=BK+1.05;
    if(backs>=2){frr=true;whisper("门，接受了。")}
    else whisper("……再一次。")}
};
var goNext=()=>{
  if(gone)return;gone=true;
  fl.style.transition="opacity 1s";fl.style.opacity="1";
  try{bgm.pause()}catch(e){}
  setTimeout(()=>{
    try{if(typeof changeMsg==="function")changeMsg("<"+D+NEXT+D+">"+"<"+SL+D+NEXT+D+">")}catch(e){}
  },1000);
};
var startAudio=()=>{
  if(started)return;started=1;
  try{bgm.volume=0.85;var pr=bgm.play();if(pr&&pr.catch)pr.catch(()=>{})}catch(e){}
};
addEventListener("keydown",e=>{
  var k=e.code;
  if(k==="KeyW"||k==="ArrowUp"){K.w=1;e.preventDefault()}
  else if(k==="KeyS"||k==="ArrowDown"){K.s=1;e.preventDefault()}
  else if(k==="KeyA"||k==="ArrowLeft"){K.a=1;e.preventDefault()}
  else if(k==="KeyD"||k==="ArrowRight"){K.d=1;e.preventDefault()}
  else if(k==="KeyQ")K.q=1;
  else if(k==="KeyE")K.e=1;
  startAudio();
});
addEventListener("keyup",e=>{
  var k=e.code;
  if(k==="KeyW"||k==="ArrowUp")K.w=0;
  else if(k==="KeyS"||k==="ArrowDown")K.s=0;
  else if(k==="KeyA"||k==="ArrowLeft")K.a=0;
  else if(k==="KeyD"||k==="ArrowRight")K.d=0;
  else if(k==="KeyQ")K.q=0;
  else if(k==="KeyE")K.e=0;
});
var dragId=null,lx=0,ly=0;
root.addEventListener("pointerdown",e=>{
  startAudio();
  if(e.target.closest(".fp-pad"))return;
  dragId=e.pointerId;lx=e.clientX;ly=e.clientY;
});
addEventListener("pointermove",e=>{
  if(e.pointerId!==dragId)return;
  ang+=(e.clientX-lx)*0.005;
  pitch=clamp(pitch-(e.clientY-ly)*0.45,-32,32);
  lx=e.clientX;ly=e.clientY;
});
addEventListener("pointerup",e=>{if(e.pointerId===dragId)dragId=null});
addEventListener("pointercancel",e=>{if(e.pointerId===dragId)dragId=null});
root.querySelectorAll(".fp-pad").forEach(b=>{
  var k=b.dataset.k;
  b.addEventListener("pointerdown",e=>{e.preventDefault();startAudio();K[k]=1});
  b.addEventListener("pointerup",()=>K[k]=0);
  b.addEventListener("pointerleave",()=>K[k]=0);
  b.addEventListener("pointercancel",()=>K[k]=0);
});
wh.classList.add("is-on");
whT=setTimeout(()=>wh.classList.remove("is-on"),4000);
var frame=(now)=>{
  if(gone)return;
  var dt=Math.min(0.05,(now-stT)*0.001);stT=now;
  if(K.q)ang-=2.6*dt;
  if(K.e)ang+=2.6*dt;
  var dx=Math.cos(ang),dy=Math.sin(ang);
  var acc=Math.min(1,dt*10);
  velF+=((K.w-K.s)-velF)*acc;
  velS+=((K.d-K.a)-velS)*acc;
  var sp=3.2*dt;
  var vx=(velF*dx-velS*dy)*sp;
  var vy=(velF*dy+velS*dx)*sp;
  var moving=Math.abs(velF)+Math.abs(velS)>0.12;
  if(moving)bobP+=dt*8.5;
  px=clamp(px+vx,-W+0.25,W-0.25);
  py=clamp(py+vy,BK+0.28,L-0.32);
  if(!frr&&py>L-1.45)glitch(1);
  else if(py<BK+0.78)glitch(2);
  else if(frr&&py>L-0.45)goNext();
  flick=0.86+Math.random()*0.16;
  var cy=IH*0.5+pitch+(moving?Math.sin(bobP)*2.6:0);
  render(g,IW,IH,buf,zb,dx,dy,cy);
  if((fc++&1)===0)render(mg,MW,MH,mbuf,mzb,-dx,-dy,MH*0.5);
  requestAnimationFrame(frame);
};
stT=performance.now();
requestAnimationFrame(frame);
})();
